// Package mascot draws omnivore's bear in the terminal, using the Kitty or iTerm2 inline image
// protocols. Terminals that support neither don't show it.
//
// The frames are generated by tools/mascot/draw.py.
package mascot

import (
	"embed"
	"encoding/base64"
	"fmt"
	"strings"
	"time"
)

//go:embed frames/*.png
var frameFS embed.FS

// Frame names.
const (
	Chomp1   = "chomp1"
	Chomp2   = "chomp2"
	Roar     = "roar"
	Happy    = "happy"
	Curious1 = "curious1"
	Curious2 = "curious2"
)

var frameNames = []string{Chomp1, Chomp2, Roar, Happy, Curious1, Curious2}

// Protocol is a terminal image protocol.
type Protocol int

const (
	None Protocol = iota
	Kitty
	ITerm2
)

func (p Protocol) String() string {
	return [...]string{"none", "kitty", "iterm2"}[p]
}

// Env is the environment variable that controls the mascot: "off", "kitty", "iterm2", or "auto"
// (the default).
const Env = "OMNIVORE_MASCOT"

// Detect picks the image protocol for the terminal described by getenv.
func Detect(getenv func(string) string) Protocol {
	switch strings.ToLower(getenv(Env)) {
	case "off", "none", "0", "false":
		return None
	case "kitty":
		return Kitty
	case "iterm2":
		return ITerm2
	}
	// Multiplexers don't pass images through without extra setup.
	if getenv("TMUX") != "" || strings.HasPrefix(getenv("TERM"), "screen") {
		return None
	}
	switch {
	case getenv("TERM") == "xterm-kitty", getenv("KITTY_WINDOW_ID") != "",
		getenv("TERM_PROGRAM") == "ghostty", getenv("TERM") == "xterm-ghostty",
		getenv("KONSOLE_VERSION") != "":
		return Kitty
	case getenv("TERM_PROGRAM") == "iTerm.app", getenv("LC_TERMINAL") == "iTerm2",
		getenv("TERM_PROGRAM") == "WezTerm":
		return ITerm2
	}
	return None
}

// Mascot encodes frames for one terminal.
type Mascot struct {
	proto      Protocol
	cols, rows int
	frames     map[string][]byte
	// shown is the Kitty image ID currently placed, or 0.
	shown int
}

// New returns a mascot that fills cols×rows cells, or nil if proto is None.
func New(proto Protocol, cols, rows int) *Mascot {
	if proto == None {
		return nil
	}
	m := &Mascot{proto: proto, cols: cols, rows: rows, frames: map[string][]byte{}}
	for _, n := range frameNames {
		b, err := frameFS.ReadFile("frames/" + n + ".png")
		if err != nil {
			panic(err) // embedded at build time
		}
		m.frames[n] = b
	}
	return m
}

// Size returns the cells the mascot covers.
func (m *Mascot) Size() (cols, rows int) { return m.cols, m.rows }

// kittyID is the image ID used for a frame. They are high, to stay clear of other programs.
func kittyID(name string) int {
	for i, n := range frameNames {
		if n == name {
			return 7_340_001 + i
		}
	}
	return 0
}

// Setup returns what must be sent once before frames are shown: for Kitty, the frames
// themselves, so that switching frames later is cheap.
func (m *Mascot) Setup() string {
	if m.proto != Kitty {
		return ""
	}
	var b strings.Builder
	for _, n := range frameNames {
		writeKittyTransmit(&b, kittyID(n), m.frames[n])
	}
	return b.String()
}

// writeKittyTransmit sends a PNG to the terminal under id, in chunks of at most 4096 base64
// bytes, with replies suppressed (q=2) so they don't arrive as keyboard input.
func writeKittyTransmit(b *strings.Builder, id int, png []byte) {
	data := base64.StdEncoding.EncodeToString(png)
	first := true
	for len(data) > 0 {
		n := min(len(data), 4096)
		chunk := data[:n]
		data = data[n:]
		more := 0
		if len(data) > 0 {
			more = 1
		}
		if first {
			fmt.Fprintf(b, "\x1b_Ga=t,f=100,i=%d,q=2,m=%d;%s\x1b\\", id, more, chunk)
			first = false
		} else {
			fmt.Fprintf(b, "\x1b_Gm=%d;%s\x1b\\", more, chunk)
		}
	}
}

// Show returns the escape sequence that draws the named frame with its top-left corner at the
// 1-based row and column, leaving the cursor where it was.
func (m *Mascot) Show(name string, row, col int) string {
	png, ok := m.frames[name]
	if !ok {
		return ""
	}
	var b strings.Builder
	b.WriteString("\x1b7") // save cursor
	switch m.proto {
	case Kitty:
		id := kittyID(name)
		if m.shown != 0 && m.shown != id {
			// Remove the previous frame's placement, keeping its image data.
			fmt.Fprintf(&b, "\x1b_Ga=d,d=i,i=%d,q=2\x1b\\", m.shown)
		}
		fmt.Fprintf(&b, "\x1b[%d;%dH\x1b_Ga=p,i=%d,p=1,c=%d,r=%d,C=1,q=2\x1b\\", row, col, id, m.cols, m.rows)
		m.shown = id
	case ITerm2:
		fmt.Fprintf(&b, "\x1b[%d;%dH\x1b]1337;File=inline=1;size=%d;width=%d;height=%d;preserveAspectRatio=1:%s\a",
			row, col, len(png), m.cols, m.rows, base64.StdEncoding.EncodeToString(png))
	}
	b.WriteString("\x1b8") // restore cursor
	return b.String()
}

// Clear returns the escape sequence that removes the mascot and frees its images.
func (m *Mascot) Clear() string {
	if m.proto != Kitty {
		return "" // iTerm2 images go with the alternate screen
	}
	var b strings.Builder
	for _, n := range frameNames {
		fmt.Fprintf(&b, "\x1b_Ga=d,d=I,i=%d,q=2\x1b\\", kittyID(n))
	}
	m.shown = 0
	return b.String()
}

// Mood is what the run looks like, which decides the frame.
type Mood struct {
	Done bool
	// Failed is the number of hosts that have failed so far.
	Failed int
	// RoarUntil is when the latest roar ends.
	RoarUntil time.Time
}

// Animation timing.
const (
	// Tick is how often the frame is chosen.
	Tick = 450 * time.Millisecond
	// RoarFor is how long the bear roars when a host fails.
	RoarFor = 1800 * time.Millisecond
)

// FrameFor chooses the frame for mood at time now; tick counts animation ticks.
//
// While hosts run the bear chomps, roaring briefly each time a host fails. When everything has
// finished it is happy, or puzzled if any host failed.
func FrameFor(mood Mood, now time.Time, tick int) string {
	switch {
	case mood.Done && mood.Failed > 0:
		if tick/2%2 == 0 {
			return Curious1
		}
		return Curious2
	case mood.Done:
		return Happy
	case now.Before(mood.RoarUntil):
		return Roar
	case tick%2 == 0:
		return Chomp1
	default:
		return Chomp2
	}
}
